class TestEmailAuthorizationCallbackView(BloomerpViewTestCase):
    """Tests function `email_authorization_callback` from `bloomerp/views/communication/email_authorization_callback.py`."""

    view_name = "email_authorization_callback"

    def setUp(self) -> None:
        """Use encrypted test credentials and an isolated provider exchange hook."""
        super().setUp()
        self.settings_override = override_settings(
            BLOOMERP_CONFIG=BloomerpConfig(email_secret_key="test-secret"),
            ALLOWED_HOSTS=["testserver", "other.example"],
            SECURE_PROXY_SSL_HEADER=("HTTP_X_FORWARDED_PROTO", "https"),
        )
        self.settings_override.enable()
        self.addCleanup(self.settings_override.disable)
        self.provider = replace(
            EmailProvider.OUTLOOK.value,
            authorization=replace(
                EmailProvider.OUTLOOK.value.authorization,
                complete=self.authorize_candidate,
            ),
            mailbox_defaults=None,
        )
        self.original_get = EMAIL_PROVIDER_REGISTRY.get
        self.registry_patch = patch.object(
            EMAIL_PROVIDER_REGISTRY, "get", side_effect=self.get_provider
        )
        self.registry_patch.start()
        self.addCleanup(self.registry_patch.stop)
        self.validation_patch = patch.object(
            self.provider.adapter_class,
            "validate_connection",
            return_value=["inbox-id", "sent-id"],
        )
        self.validation_patch.start()
        self.addCleanup(self.validation_patch.stop)
        self.exchange_calls = 0

    def get_provider(self, key: str | None) -> Any:
        """Return the test definition only for the registered authorization provider."""
        return self.provider if key == "outlook" else self.original_get(key)

    def authorize_candidate(
        self,
        adapter: BaseEmailAdapter,
        *,
        code: str,
        redirect_uri: str,
        code_verifier: str,
    ) -> None:
        """Simulate a verified provider response without contacting a mailbox."""
        self.exchange_calls += 1
        self.assertEqual(code, "authorization-code")
        self.assertEqual(redirect_uri, "https://testserver" + reverse(self.view_name))
        self.assertGreaterEqual(len(code_verifier), 43)
        adapter.email_account.set_access_token_secret("access-secret")
        adapter.email_account.set_refresh_token_secret("refresh-secret")
        adapter.email_account.token_expires_at = timezone.now() + timedelta(hours=1)

    def prepare_authorization(self, scenario: RequestScenario) -> None:
        """Start the actual wizard and extract its opaque state and PKCE request."""
        self.start_authorization(scenario, account=None)

    def prepare_reconnect(self, scenario: RequestScenario) -> None:
        """Start reauthorization for an existing account without replacing its identity."""
        self.account = EmailAccount.objects.create(
            email_address="mailbox@example.com", provider="outlook",
            oauth_client_id="previous-client", oauth_client_secret="previous-secret",
            oauth_tenant_id="11111111-1111-1111-1111-111111111111",
            access_token="old-access", refresh_token="old-refresh",
            status=EmailAccount.Status.ERROR,
        )
        self.start_authorization(scenario, account=self.account)

    def start_authorization(self, scenario: RequestScenario, *, account: EmailAccount | None) -> None:
        """Exercise a create or reconnect wizard and inspect the consent request."""
        scenario.headers = {"Host": "testserver", **(scenario.headers or {})}
        self.exchange_calls = 0
        self.client.force_login(self.admin_user)
        url = reverse("email_accounts_detail_reconfigure_email_account", kwargs={"pk": account.pk}) if account else reverse("email_accounts_add")
        self.wizard_url = url
        self.client.get(url, {"reset_wizard": "true"}, secure=True)
        self.client.post(url, {"provider": "outlook"}, secure=True)
        response = self.client.post(
            url,
            {
                "email_address": "mailbox@example.com",
                "oauth_client_id": "client-id",
                "oauth_client_secret": "client-secret",
                "oauth_tenant_id": "11111111-1111-1111-1111-111111111111",
                "set_as_default": "on",
            },
            secure=True,
            headers={"HX-Request": "true"},
        )
        self.assertEqual(response.status_code, 200)
        query = parse_qs(urlsplit(response["HX-Redirect"]).query)
        self.assertEqual(query["code_challenge_method"], ["S256"])
        self.assertIn("Mail.Send", query["scope"][0])
        self.assertNotIn("client-secret", response["HX-Redirect"])
        self.assertEqual(EmailAccount.objects.filter(email_address="mailbox@example.com").count(), int(account is not None))
        self.attempt = EmailAuthorizationRequest.objects.get()
        self.assertNotIn("client-secret", self.attempt.payload)
        self.assertNotIn(query["state"][0], self.attempt.state_digest)
        self.state = query["state"][0]
        scenario.query_params = {"state": self.state, "code": "authorization-code"}

    def change_configuration(self, scenario: RequestScenario) -> None:
        """Invalidate consent when a different editor changes its application settings."""
        EmailAccount.objects.filter(pk=self.account.pk).update(oauth_client_id="another-client")

    def reconnected_account_is_current(self, response: HttpResponse) -> bool:
        """Save the new grant while preserving synchronization progress written in parallel."""
        cursor = {"mailboxes": {"inbox-id": {"url": "committed-progress"}}}
        EmailAccount.objects.filter(pk=self.account.pk).update(sync_cursor=cursor)
        mapping = {"inbox-id": {"label": "Inbox", "main_folder": True}, "sent-id": {"label": "Sent", "sent_folder": True}}
        saved = self.client.post(self.wizard_url, {"mailboxes": json.dumps(mapping)}, secure=True)
        self.assertEqual(saved.status_code, 302)
        self.account.refresh_from_db()
        return self.account.sync_cursor == cursor and self.account.get_access_token_secret() == "access-secret" and self.account.oauth_client_id == "client-id"

    def disconnected_account_stays_disconnected(self, response: HttpResponse) -> bool:
        """Reject saving already-completed consent after a later disconnect invalidates it."""
        disconnected = self.client.post(reverse("email_accounts_detail_disconnect_email_account", kwargs={"pk": self.account.pk}))
        self.assertEqual(disconnected.status_code, 200)
        mapping = {"inbox-id": {"label": "Inbox", "main_folder": True}, "sent-id": {"label": "Sent", "sent_folder": True}}
        saved = self.client.post(self.wizard_url, {"mailboxes": json.dumps(mapping)}, secure=True)
        self.assertEqual(saved.status_code, 200)
        self.account.refresh_from_db()
        return not self.account.access_token and not self.account.sync_enabled and saved.context_data["step_index"] == 1

    def expire_authorization(self, scenario: RequestScenario) -> None:
        """Make a previously valid authorization expire before its callback."""
        EmailAuthorizationRequest.objects.update(
            expires_at=timezone.now() - timedelta(seconds=1)
        )

    def change_browser(self, scenario: RequestScenario) -> None:
        """Replace the initiating browser binding while retaining the same actor."""
        session = self.client.session
        session["email_authorization_browser"] = "another-browser"
        session.save()

    def deny_consent(self, scenario: RequestScenario) -> None:
        """Simulate provider cancellation without reflecting remote descriptions."""
        scenario.query_params = {
            "state": self.state,
            "error": "access_denied",
            "error_description": "private-remote-detail",
        }

    def replay_callback(self, scenario: RequestScenario) -> None:
        """Consume an authorization before issuing the identical callback again."""
        response = self.client.get(
            reverse(self.view_name), scenario.query_params, secure=True
        )
        self.assertEqual(response.status_code, 302)
        self.exchange_calls = 0

    def authorization_saved(self, response: HttpResponse) -> bool:
        """Save mapped folders after consent and verify secrets/default sender persist."""
        self.assertEqual(self.exchange_calls, 1)
        self.assertFalse(EmailAuthorizationRequest.objects.exists())
        self.assertFalse(
            EmailAccount.objects.filter(email_address="mailbox@example.com").exists()
        )
        mapping = {
            "inbox-id": {"label": "Incoming", "main_folder": True},
            "sent-id": {"label": "Sent", "sent_folder": True},
        }
        completed = self.client.post(
            reverse("email_accounts_add"),
            {"mailboxes": json.dumps(mapping)},
            secure=True,
        )
        self.assertEqual(completed.status_code, 302)
        account = EmailAccount.objects.get(email_address="mailbox@example.com")
        self.admin_user.refresh_from_db()
        return (
            account.status == EmailAccount.Status.ACTIVE
            and account.get_access_token_secret() == "access-secret"
            and account.access_token != "access-secret"
            and account.get_oauth_client_secret() == "client-secret"
            and self.admin_user.default_email_account_id == account.pk
        )

    def exchange_not_called(self, response: HttpResponse) -> bool:
        """Reject a mismatched callback before exchanging any remote code."""
        return self.exchange_calls == 0

    def cancellation_is_safe(self, response: HttpResponse) -> bool:
        """Keep denied consent inactive and consume its state without reflecting diagnostics."""
        wizard = self.client.session["email_account_create_wizard"]
        return (
            self.exchange_calls == 0
            and not EmailAuthorizationRequest.objects.exists()
            and not EmailAccount.objects.filter(
                email_address="mailbox@example.com"
            ).exists()
            and wizard["__wizard_step"] == 1
            and "private-remote-detail" not in str(wizard)
        )

